INSERT INTO item(user_id,service_id) SELECT #{userId}, s.service_id FROM services s WHERE s.service_id IN
#{sid}
AND NOT EXISTS ( SELECT 1 FROM item i WHERE i.user_id = #{userId} AND i.service_id = s.service_id AND i.manage_status = 0 AND i.create_time > DATE_SUB(NOW(), INTERVAL 60 SECOND) )

INSERT INTO item(user_id, service_id, consultant_id, slot_id, slot_date, start_time, end_time)
SELECT #{userId}, #{serviceId}, #{consultantId}, #{slotId}, #{slotDate}, #{startTime}, #{endTime}
WHERE NOT EXISTS (
    SELECT 1 FROM item i
    WHERE i.user_id = #{userId}
      AND i.consultant_id = #{consultantId}
      AND i.slot_id = #{slotId}
      AND i.manage_status = 0
      AND i.create_time > DATE_SUB(NOW(), INTERVAL 60 SECOND)
)

